'use client';

import { useLayoutEffect, useRef, useState } from 'react';

import { FileTextIcon } from '@/registry/ndeko/lib/icons';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import {
  DOCUMENT_NAME,
  fieldOf,
  FIELDS,
  type ExtractField,
  type FieldId,
  type PageNumber,
} from './data';
import { DocumentPage } from './document';
import { FieldList, JsonPanel, SchemaPanel } from './fields';
import {
  INITIAL,
  isReadingDone,
  LOOP_AFTER_MS,
  pendingIdsOf,
  reducer,
  RESTING,
  reviewOf,
  SAVE_MS,
  SCRIPT,
  type ExtractState,
  type ExtractTab,
} from './session';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const TAB_SEGMENTS: Segment<ExtractTab>[] = [
  { value: 'fields', label: 'Fields' },
  { value: 'json', label: 'JSON' },
  { value: 'schema', label: 'Schema' },
];

const PAGE_SEGMENTS: Segment<'1' | '2'>[] = [
  { value: '1', label: 'Page 1' },
  { value: '2', label: 'Page 2' },
];

const SAVE_LABELS: Record<MorphState, string> = {
  idle: 'Accept all',
  busy: 'Saving',
  done: 'Saved',
};

function pageOf(value: '1' | '2'): PageNumber {
  if (value === '2') {
    return 2;
  }
  return 1;
}

function statusOf(state: ExtractState) {
  if (state.save === 'done') {
    return 'Saved to your records';
  }
  if (!isReadingDone(state)) {
    return `Reading page ${state.page}`;
  }
  const pending = pendingIdsOf(state).length;
  if (pending === 0) {
    return 'Every value is checked';
  }
  if (pending === 1) {
    return '1 value needs a look';
  }
  return `${pending} values need a look`;
}

function activeOf(
  hovered: FieldId | null,
  pointed: FieldId | null,
  isAutoplaying: boolean
) {
  if (hovered) {
    return hovered;
  }
  if (isAutoplaying) {
    return pointed;
  }
  return null;
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function middleOf(box: DOMRect) {
  return box.top + box.height / 2;
}

/**
 * The thread from a value on the page to its row is written to the path directly: pointing at
 * a value re-renders nothing but the two things it lights.
 */
function useThread(
  wrapperRef: React.RefObject<HTMLDivElement | null>,
  pathRef: React.RefObject<SVGPathElement | null>,
  activeId: FieldId | null,
  layoutKey: string
) {
  useLayoutEffect(() => {
    const wrapper = wrapperRef.current;
    const path = pathRef.current;
    if (!wrapper || !path) {
      return;
    }
    const box = wrapper.querySelector(`[data-box='${activeId}']`);
    const row = wrapper.querySelector(`[data-row='${activeId}']`);
    if (!box || !row) {
      path.style.opacity = '0';
      return;
    }
    const frame = wrapper.getBoundingClientRect();
    const from = box.getBoundingClientRect();
    const to = row.getBoundingClientRect();
    const startX = from.right - frame.left;
    const endX = to.left - frame.left;
    const isSideBySide = endX > startX;
    if (!isSideBySide) {
      path.style.opacity = '0';
      return;
    }
    const startY = middleOf(from) - frame.top;
    const endY = middleOf(to) - frame.top;
    const bendX = (startX + endX) / 2;
    const curve = `M ${startX} ${startY} C ${bendX} ${startY}, ${bendX} ${endY}, ${endX} ${endY}`;
    path.setAttribute('d', curve);
    path.style.transition = 'none';
    path.style.strokeDashoffset = '1';
    path.style.opacity = '1';
    path.getBoundingClientRect();
    path.style.transition = '';
    path.style.strokeDashoffset = '0';
  }, [wrapperRef, pathRef, activeId, layoutKey]);
}

export default function AgentReview03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const [hovered, setHovered] = useState<FieldId | null>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const pathRef = useRef<SVGPathElement>(null);
  const { schedule } = useTimeouts();
  const activeId = activeOf(hovered, state.pointed, isAutoplaying);
  const layoutKey = `${state.page}:${state.tab}:${state.shown}`;
  useThread(wrapperRef, pathRef, activeId, layoutKey);
  const readFields = FIELDS.slice(0, state.shown);
  const readIds = new Set(readFields.map((field) => field.id));
  const pendingCount = pendingIdsOf(state).length;
  const canAccept = isReadingDone(state) && pendingCount === 0;
  const status = statusOf(state);
  const message = spokenUnless(isAutoplaying, status);
  const canReplay = isFinished && !isAutoplaying;

  function valueOf(field: ExtractField) {
    return state.edits[field.id] ?? field.value;
  }

  function pick(id: FieldId) {
    const field = fieldOf(id);
    act({ type: 'page', page: field.page });
    act({ type: 'tab', tab: 'fields' });
  }

  function accept() {
    act({ type: 'saving' });
    schedule(() => act({ type: 'saved' }), SAVE_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-3 @3xl:p-8'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-4'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <span
              aria-hidden='true'
              className='keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md'
            >
              <FileTextIcon className='size-3.5' />
            </span>
            <div className='flex min-w-40 flex-1 flex-col leading-tight'>
              <h1 className='truncate font-mono text-[13px] font-medium'>
                {DOCUMENT_NAME}
              </h1>
              <Swap swapKey={status} className='text-muted-foreground text-xs'>
                {status}
              </Swap>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Read it again'
            />
          </header>

          <div
            ref={wrapperRef}
            className='relative flex flex-col gap-4 @3xl:flex-row @3xl:items-start @3xl:gap-10'
          >
            <section
              aria-label='Document'
              className='bg-foreground/[0.03] flex min-w-0 flex-1 flex-col gap-3 rounded-xl p-3'
            >
              <div className='flex items-center justify-between gap-2'>
                <Segments
                  label='Page'
                  value={`${state.page}`}
                  segments={PAGE_SEGMENTS}
                  onValueChange={(value) =>
                    act({ type: 'page', page: pageOf(value) })
                  }
                />
                <span className='text-muted-foreground text-xs'>2 pages</span>
              </div>
              <DocumentPage
                page={state.page}
                activeId={activeId}
                readIds={readIds}
                onPoint={setHovered}
                onPick={pick}
              />
            </section>

            <section
              aria-label='Extraction'
              className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:w-[22rem] @3xl:shrink-0'
            >
              <div className='flex items-center justify-between gap-2'>
                <Segments
                  label='View'
                  value={state.tab}
                  segments={TAB_SEGMENTS}
                  onValueChange={(tab) => act({ type: 'tab', tab })}
                />
                <span className='text-muted-foreground text-xs tabular-nums'>
                  {state.shown} of {FIELDS.length}
                </span>
              </div>

              <div className='min-h-[13rem]'>
                {state.tab === 'fields' && (
                  <FieldList
                    shown={state.shown}
                    activeId={activeId}
                    pressed={pressed}
                    valueOf={valueOf}
                    reviewOf={(id) => reviewOf(state, id)}
                    onPoint={setHovered}
                    onPick={pick}
                    onConfirm={(id) => act({ type: 'confirmed', id })}
                    onEdit={(id, value) => act({ type: 'edited', id, value })}
                  />
                )}
                {state.tab === 'json' && (
                  <JsonPanel shown={state.shown} valueOf={valueOf} />
                )}
                {state.tab === 'schema' && <SchemaPanel />}
              </div>

              <div className='flex items-center justify-between gap-3'>
                <span className='text-muted-foreground text-xs'>
                  Illustrative confidence
                </span>
                <MorphButton
                  type='button'
                  size='sm'
                  state={state.save}
                  labels={SAVE_LABELS}
                  disabled={!canAccept}
                  onClick={accept}
                  className={pressedSolidOf(pressed === 'accept')}
                />
              </div>
            </section>

            <svg
              aria-hidden='true'
              className='pointer-events-none absolute inset-0 hidden size-full overflow-visible @3xl:block'
            >
              <path
                ref={pathRef}
                pathLength={1}
                strokeDasharray='1'
                fill='none'
                strokeWidth='1.5'
                strokeLinecap='round'
                className='stroke-primary opacity-0 transition-[stroke-dashoffset] duration-300 ease-(--ease-out-strong) motion-reduce:transition-none'
              />
            </svg>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';

import { fieldOf, LINE_ITEMS, type FieldId, type PageNumber } from './data';

export type PointHandlers = {
  activeId: FieldId | null;
  /** The fields read so far: their boxes are marked on the page. */
  readIds: ReadonlySet<FieldId>;
  onPoint: (id: FieldId | null) => void;
  onPick: (id: FieldId) => void;
};

function boxToneOf(isActive: boolean, isRead: boolean) {
  if (isActive) {
    return 'bg-primary/15 ring-primary/60';
  }
  if (isRead) {
    return 'bg-primary/[0.06] ring-primary/25';
  }
  return 'ring-transparent';
}

type BoxProps = PointHandlers & {
  id: FieldId;
  className?: string;
};

/** A value on the page. It lights with its row in the list, whichever of the two is pointed at. */
function Box({ id, activeId, readIds, onPoint, onPick, className }: BoxProps) {
  const field = fieldOf(id);
  const isActive = activeId === id;
  const isRead = readIds.has(id);

  return (
    <button
      type='button'
      data-box={id}
      aria-label={`${field.label}: ${field.printed}`}
      onMouseEnter={() => onPoint(id)}
      onMouseLeave={() => onPoint(null)}
      onFocus={() => onPoint(id)}
      onBlur={() => onPoint(null)}
      onClick={() => onPick(id)}
      className={cn(
        'hairline-ring focus-visible:ring-ring -mx-1 cursor-pointer rounded-sm px-1 text-start font-medium transition-[background-color,box-shadow] duration-200 outline-none focus-visible:ring-2',
        boxToneOf(isActive, isRead),
        className
      )}
    >
      {field.printed}
    </button>
  );
}

function Caption({ children }: { children: React.ReactNode }) {
  return <span className='text-muted-foreground'>{children}</span>;
}

function FirstPage(handlers: PointHandlers) {
  return (
    <div className='flex flex-col gap-5'>
      <div className='flex items-start justify-between gap-3'>
        <div className='flex flex-col'>
          <span className='text-base font-semibold'>Purchase order</span>
          <Caption>Tallis Studio</Caption>
        </div>
        <div className='flex flex-col items-end'>
          <Caption>Number</Caption>
          <Box id='po_number' {...handlers} />
        </div>
      </div>
      <div className='flex flex-col'>
        <Caption>Order date</Caption>
        <span>
          <Box id='order_date' {...handlers} />
        </span>
      </div>
      <div className='grid grid-cols-2 gap-4'>
        <div className='flex flex-col'>
          <Caption>Supplier</Caption>
          <span>
            <Box id='supplier' {...handlers} />
          </span>
          <span>22 Dock Road, Rotterdam</span>
        </div>
        <div className='flex flex-col'>
          <Caption>Bill to</Caption>
          <span>
            <Box id='bill_to' {...handlers} />
          </span>
          <span>Lisbon</span>
        </div>
      </div>
      <div className='flex flex-col'>
        <Caption>Ship to</Caption>
        <span>Warehouse 3, same address</span>
      </div>
    </div>
  );
}

function SecondPage(handlers: PointHandlers) {
  return (
    <div className='flex flex-col gap-5'>
      <table className='w-full text-start'>
        <thead>
          <tr className='text-muted-foreground'>
            <th className='pb-1 text-start font-normal'>Item</th>
            <th className='w-10 pb-1 text-end font-normal'>Qty</th>
            <th className='w-20 pb-1 text-end font-normal'>Amount</th>
          </tr>
        </thead>
        <tbody>
          {LINE_ITEMS.map((item) => (
            <tr key={item.name} className='hairline-t border-border'>
              <td className='py-1.5 pe-2'>{item.name}</td>
              <td className='py-1.5 text-end tabular-nums'>{item.quantity}</td>
              <td className='py-1.5 text-end tabular-nums'>{item.amount}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className='flex items-center justify-end gap-3'>
        <Caption>Total</Caption>
        <Box id='currency' {...handlers} />
        <Box id='total' {...handlers} className='text-sm tabular-nums' />
      </div>
      <div className='grid grid-cols-2 gap-4'>
        <div className='relative flex flex-col'>
          <Caption>Payment terms</Caption>
          <span>
            <Box id='payment_terms' {...handlers} />
          </span>
          <span
            aria-label='Handwritten note: Net 45'
            className='text-info-foreground absolute start-14 top-7 -rotate-6 font-medium'
          >
            Net 45?
          </span>
        </div>
        <div className='relative flex flex-col'>
          <Caption>Delivery date</Caption>
          <span>
            <Box id='delivery_date' {...handlers} />
          </span>
          <span
            aria-label='Stamp: Received'
            className='text-destructive-ink/70 border-destructive-ink/50 absolute start-12 top-3 rotate-[-8deg] rounded-sm border px-1.5 py-0.5 font-semibold'
          >
            Received
          </span>
        </div>
      </div>
    </div>
  );
}

type DocumentPageProps = PointHandlers & {
  page: PageNumber;
};

export function DocumentPage({ page, ...handlers }: DocumentPageProps) {
  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] min-h-[19rem] rounded-lg p-5 text-xs leading-relaxed shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      {page === 1 && <FirstPage {...handlers} />}
      {page === 2 && <SecondPage {...handlers} />}
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useState } from 'react';

import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { JsonView } from '@/registry/ndeko/ui/json-view';

import {
  FIELDS,
  isLowConfidence,
  type ExtractField,
  type FieldId,
} from './data';
import type { ReviewStatus } from './session';

const REVIEW_WORD: Record<ReviewStatus, string> = {
  pending: 'Needs a look',
  confirmed: 'Confirmed',
  edited: 'Edited',
};

function confidenceVariantOf(field: ExtractField, review: ReviewStatus) {
  const isSettled = review !== 'pending';
  if (isLowConfidence(field) && !isSettled) {
    return 'warning';
  }
  return 'success';
}

function chipTextOf(field: ExtractField, review: ReviewStatus) {
  const isSettled = review !== 'pending';
  if (isLowConfidence(field) && isSettled) {
    return REVIEW_WORD[review];
  }
  return `${field.confidence}%`;
}

function rowToneOf(isActive: boolean) {
  if (isActive) {
    return 'bg-primary/10';
  }
  return 'hover:bg-foreground/[0.04]';
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

type FlaggedBodyProps = {
  field: ExtractField;
  value: string;
  isPressed: boolean;
  onConfirm: (id: FieldId) => void;
  onEdit: (id: FieldId, value: string) => void;
};

function FlaggedBody({
  field,
  value,
  isPressed,
  onConfirm,
  onEdit,
}: FlaggedBodyProps) {
  const [draft, setDraft] = useState<string | null>(null);
  const isEditing = draft !== null;

  function save() {
    const next = draft?.trim() ?? '';
    setDraft(null);
    if (next !== '') {
      onEdit(field.id, next);
    }
  }

  function handleKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      save();
    }
    if (event.key === 'Escape') {
      setDraft(null);
    }
  }

  return (
    <div className='flex flex-col gap-2 px-2 pb-2'>
      <p className='text-warning-foreground text-xs'>{field.reason}</p>
      {!isEditing && (
        <div className='flex items-center gap-2'>
          <Button
            type='button'
            size='sm'
            onClick={() => onConfirm(field.id)}
            className={pressedSolidOf(isPressed)}
          >
            Confirm {value}
          </Button>
          <Button
            type='button'
            size='sm'
            variant='outline'
            onClick={() => setDraft(value)}
          >
            Edit
          </Button>
        </div>
      )}
      {isEditing && (
        <div className='flex items-center gap-2'>
          <input
            value={draft}
            autoFocus
            aria-label={`${field.label}, corrected value`}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={handleKeys}
            className='bg-card hairline-ring ring-foreground/15 focus-visible:ring-ring/25 dark:bg-foreground/[0.04] h-7 min-w-0 flex-1 rounded-md px-2 text-base outline-none focus-visible:ring-[3px] md:text-[13px]'
          />
          <Button type='button' size='sm' onClick={save}>
            Save
          </Button>
        </div>
      )}
    </div>
  );
}

export type FieldListProps = {
  shown: number;
  activeId: FieldId | null;
  pressed: string | null;
  valueOf: (field: ExtractField) => string;
  reviewOf: (id: FieldId) => ReviewStatus;
  onPoint: (id: FieldId | null) => void;
  onPick: (id: FieldId) => void;
  onConfirm: (id: FieldId) => void;
  onEdit: (id: FieldId, value: string) => void;
};

export function FieldList({
  shown,
  activeId,
  pressed,
  valueOf,
  reviewOf,
  onPoint,
  onPick,
  onConfirm,
  onEdit,
}: FieldListProps) {
  const shouldReduceMotion = useReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const fields = FIELDS.slice(0, shown);

  return (
    <ul aria-label='Fields read from the document' className='flex flex-col'>
      <AnimatePresence initial={false}>
        {fields.map((field) => {
          const review = reviewOf(field.id);
          const value = valueOf(field);
          const needsLook = isLowConfidence(field) && review === 'pending';
          const chipText = chipTextOf(field, review);
          return (
            <motion.li
              key={field.id}
              className='overflow-hidden'
              {...rowPresence}
            >
              <div
                className={cn(
                  'rounded-lg transition-colors duration-150',
                  rowToneOf(activeId === field.id)
                )}
              >
                <button
                  type='button'
                  data-row={field.id}
                  onMouseEnter={() => onPoint(field.id)}
                  onMouseLeave={() => onPoint(null)}
                  onFocus={() => onPoint(field.id)}
                  onBlur={() => onPoint(null)}
                  onClick={() => onPick(field.id)}
                  className='focus-visible:ring-ring/25 flex min-h-11 w-full cursor-pointer items-center gap-3 rounded-lg px-2 py-1.5 text-start outline-none focus-visible:ring-[3px]'
                >
                  <span className='flex min-w-0 flex-1 flex-col leading-tight'>
                    <span className='text-muted-foreground text-xs'>
                      {field.label}
                    </span>
                    <span className='truncate text-[13px] font-medium tabular-nums'>
                      {value}
                    </span>
                  </span>
                  <Badge variant={confidenceVariantOf(field, review)}>
                    <Swap swapKey={chipText} className='tabular-nums'>
                      {chipText}
                    </Swap>
                  </Badge>
                </button>
                <Fold open={needsLook}>
                  <FlaggedBody
                    field={field}
                    value={value}
                    isPressed={pressed === `confirm-${field.id}`}
                    onConfirm={onConfirm}
                    onEdit={onEdit}
                  />
                </Fold>
              </div>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ul>
  );
}

function typedValueOf(field: ExtractField, value: string) {
  if (field.type === 'number') {
    return Number(value);
  }
  return value;
}

export function JsonPanel({
  shown,
  valueOf,
}: {
  shown: number;
  valueOf: (field: ExtractField) => string;
}) {
  const record: Record<string, string | number> = {};
  for (const field of FIELDS.slice(0, shown)) {
    record[field.id] = typedValueOf(field, valueOf(field));
  }

  return <JsonView value={record} className='text-xs' />;
}

export function SchemaPanel() {
  return (
    <ul aria-label='Schema' className='flex flex-col'>
      {FIELDS.map((field) => (
        <li
          key={field.id}
          className='flex h-9 items-center justify-between gap-3 px-2 text-[13px]'
        >
          <code className='truncate font-mono text-xs'>{field.id}</code>
          <Badge variant='secondary' className='font-mono'>
            {field.type}
          </Badge>
        </li>
      ))}
    </ul>
  );
}

import { FIELDS, FLAGGED_IDS, type FieldId, type PageNumber } from './data';
import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

export type ExtractTab = 'fields' | 'json' | 'schema';

export type ReviewStatus = 'pending' | 'confirmed' | 'edited';

export type SaveStatus = 'idle' | 'busy' | 'done';

export type ExtractState = {
  shown: number;
  page: PageNumber;
  tab: ExtractTab;
  /** The field the demonstration points at; a person's own pointer wins over it. */
  pointed: FieldId | null;
  review: Partial<Record<FieldId, ReviewStatus>>;
  edits: Partial<Record<FieldId, string>>;
  save: SaveStatus;
};

export type ExtractAction =
  | { type: 'read' }
  | { type: 'page'; page: PageNumber }
  | { type: 'tab'; tab: ExtractTab }
  | { type: 'pointed'; id: FieldId | null }
  | { type: 'confirmed'; id: FieldId }
  | { type: 'edited'; id: FieldId; value: string }
  | { type: 'saving' }
  | { type: 'saved' };

type Step = SessionStep<ExtractState, ExtractAction>;

export const INITIAL: ExtractState = {
  shown: 0,
  page: 1,
  tab: 'fields',
  pointed: null,
  review: {},
  edits: {},
  save: 'idle',
};

export function reviewOf(state: ExtractState, id: FieldId): ReviewStatus {
  return state.review[id] ?? 'pending';
}

export function pendingIdsOf(state: ExtractState) {
  return FLAGGED_IDS.filter((id) => reviewOf(state, id) === 'pending');
}

export function isReadingDone(state: ExtractState) {
  return state.shown >= FIELDS.length;
}

/** The viewer follows the page the agent is reading. */
function read(state: ExtractState): ExtractState {
  const field = FIELDS[state.shown];
  if (!field) {
    return state;
  }
  return { ...state, shown: state.shown + 1, page: field.page };
}

function saving(state: ExtractState): ExtractState {
  const hasPending = pendingIdsOf(state).length > 0;
  const canSave = isReadingDone(state) && !hasPending;
  if (!canSave || state.save !== 'idle') {
    return state;
  }
  return { ...state, save: 'busy' };
}

function saved(state: ExtractState): ExtractState {
  if (state.save !== 'busy') {
    return state;
  }
  return { ...state, save: 'done' };
}

export function reducer(
  state: ExtractState,
  action: ExtractAction
): ExtractState {
  switch (action.type) {
    case 'read':
      return read(state);
    case 'page':
      return { ...state, page: action.page };
    case 'tab':
      return { ...state, tab: action.tab };
    case 'pointed':
      return { ...state, pointed: action.id };
    case 'confirmed': {
      const review = { ...state.review, [action.id]: 'confirmed' as const };
      return { ...state, review };
    }
    case 'edited': {
      const review = { ...state.review, [action.id]: 'edited' as const };
      const edits = { ...state.edits, [action.id]: action.value };
      return { ...state, review, edits };
    }
    case 'saving':
      return saving(state);
    case 'saved':
      return saved(state);
  }
}

function readSteps(): Step[] {
  return FIELDS.map((_, index) => {
    const after = delayOfRead(index);
    return { after, action: { type: 'read' } };
  });
}

function delayOfRead(index: number) {
  if (index === 0) {
    return 1100;
  }
  return 520;
}

function isReviewed(id: FieldId) {
  return (state: ExtractState) => reviewOf(state, id) !== 'pending';
}

export const SAVE_MS = 900;

/** A request that waits on a person is answered by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

export const SCRIPT: Step[] = [
  ...readSteps(),
  { after: 900, by: 'demo', action: { type: 'pointed', id: 'total' } },
  { after: 1700, by: 'demo', action: { type: 'pointed', id: 'payment_terms' } },
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'confirm-payment_terms',
    action: { type: 'confirmed', id: 'payment_terms' },
    isAnswered: isReviewed('payment_terms'),
  },
  { after: 500, by: 'demo', action: { type: 'pointed', id: 'delivery_date' } },
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'confirm-delivery_date',
    action: { type: 'confirmed', id: 'delivery_date' },
    isAnswered: isReviewed('delivery_date'),
  },
  { after: 500, by: 'demo', action: { type: 'pointed', id: null } },
  { after: 1300, by: 'demo', press: 'accept', action: { type: 'saving' } },
  { after: SAVE_MS, action: { type: 'saved' } },
];

function restingOf() {
  let state = INITIAL;
  for (const step of SCRIPT) {
    state = reducer(state, step.action);
  }
  return state;
}

export const RESTING = restingOf();

export const LOOP_AFTER_MS = 3200;

export type FieldId =
  | 'po_number'
  | 'order_date'
  | 'supplier'
  | 'bill_to'
  | 'currency'
  | 'total'
  | 'payment_terms'
  | 'delivery_date';

export type PageNumber = 1 | 2;

export type ExtractField = {
  id: FieldId;
  label: string;
  type: 'string' | 'date' | 'number';
  value: string;
  /** How the value is printed on the page, when the document writes it another way. */
  printed: string;
  page: PageNumber;
  /** Between 0 and 100. Illustrative: the demonstration does not read a real document. */
  confidence: number;
  /** Why a person should look, for a value read with low confidence. */
  reason?: string;
};

